fn gizmo_axis_allowed(
    dimension: SceneViewDimension,
    mode: GizmoMode,
    axis: GizmoAxis,
) -> bool {
    match (dimension, mode) {
        (SceneViewDimension::ThreeD, _) => true,
        (SceneViewDimension::TwoD, GizmoMode::Rotate) => axis == GizmoAxis::Z,
        (SceneViewDimension::TwoD, GizmoMode::Translate | GizmoMode::Scale) => {
            matches!(axis, GizmoAxis::X | GizmoAxis::Y)
        }
    }
}

